def checked_payload(raw,bindings):
    if len(raw)!=SIZE or sha(raw)!=RAW_SHA or bindings!=BINDINGS:raise ValueError('Dispatcher compiled body or bindings changed')
    return raw,bindings

def normalized_payload(raw,bindings):
    checked_payload(raw,bindings)
    words=list(struct.unpack('>252I',raw));mapped={i:i for i in range(0,1008,4)}
    # Cycle independent low-half address instructions before their first uses.
    mapped.update({0x9C:0xA0,0xA0:0xA4,0xA4:0x9C})
    # Move only independent pointer/end setup and the first flag comparison.
    mapped.update({0x2B8:0x33C,0x2BC:0x340,0x2C4:0x2B8,0x2D4:0x2C4,0x2F0:0x2BC})
    mapped.update({i+4:i for i in range(0x2D4,0x2EC,4)})
    mapped.update({i+8:i for i in range(0x2EC,0x33C,4)})
    assert sorted(mapped.values())==list(range(0,1008,4))
    out=[words[mapped[i]//4]for i in range(0,1008,4)];newbindings={i:list(bindings[mapped[i]])for i in mapped if mapped[i]in bindings}
    def rename(at,roles):
        w=out[at//4];op=w>>26;rs=w>>21&31;rt=w>>16&31
        assert op in (0x0F,0x09,0x20,0x28,0x06,0x0A,0x04,0x05,0x15),hex(w)
        out[at//4]=(w&~((31<<21)|(31<<16)))|(roles.get(rs,rs)<<21)|(roles.get(rt,rt)<<16)
    for at in(0x2B8,0x2BC):rename(at,{2:17})
    for at in(0x2C4,0x2F0):rename(at,{4:3})
    for at in range(0x344,0x3D0,4):rename(at,{2:17,3:2,4:3})
    assert out[0x2CC//4]==0x10000005
    out[0x2CC//4]=0x10000006
    # Both counters begin at zero, increment once on every path, and stop at 11.
    # Equality and signed-bound forms are equivalent on the complete reachable range.
    for at,target in((0x84,0x3C),(0x2A4,0x270)):
        assert out[at//4]==0x2401000B and out[at//4+1]>>16==0x1601
        assert (at+8)+((out[at//4+1]&65535)-65536)*4==target
        out[at//4]=0x2A01000B;out[at//4+1]=0x14200000|(out[at//4+1]&65535)
    # A delayed HI16 must retain a distinct alias until its own LO16 use.
    # Sharing D_800DDF68 here would bind the end HI16 to an intervening flag LO16
    # when base+11 crosses a signed low-half carry boundary.
    assert out[0x2F0//4]==0x2463000B
    out[0x2F0//4]=0x24630000
