    struct.pack_into('>I',result,target[0][0]+8,SIZE)
    cycles=((('D_800DDF64','D_800A24B0','D_80090A90','D_80090930'),(1,2,3,0),(2755492,2755508,2755524,2755540)),(('func_150B73F0','D_8009DA4C','D_800A601C','D_8009E7D4'),(3,0,1,2),(2974884,2974900,2974916,2974932)),(('D_800A72E8','D_80091618'),(1,0),(3014548,3014564)))
