def check_image(before,actual,truth):
    if actual!=predicted_image(before,truth):raise ValueError('Dispatcher whole image differs from explicit prediction')
    if Counter((n,f[1],SIZE if n==FUNCTION else f[2],*f[3:])for _,n,f,_ in symbol_rows(before))!=Counter((n,*f[1:])for _,n,f,_ in symbol_rows(actual)):raise ValueError('Dispatcher named ELF definitions changed')

