def verify_prepared(output):
    rows=json.loads((output/'canonical-prepared-fingerprint.json').read_text())
    if set(rows)!=set(EVIDENCE):raise ValueError('Dispatcher prepared evidence set changed')
    for name,wanted in rows.items():
        if sha((output/name).read_bytes())!=wanted:raise ValueError('Dispatcher prepared evidence changed: '+name)
